function fixed(a, b) {
  if (a === b) return a;
  const L = a.length;
  // find common prefix length
  let i = 0;
  while (i < L && a[i] === b[i]) i++;
  const prefix = a.slice(0, i);
  const aSuf = a.slice(i);   // length L-i
  const bSuf = b.slice(i);
  // first chars differ
  const ad = aSuf[0], bd = bSuf[0];
  const remLen = aSuf.length - 1;
  const parts = [];
  // group 1: a's branch: ad + fixed(aSuf.slice(1), '9'.repeat(remLen))
  if (remLen === 0) {
    parts.push(ad);
  } else {
    const sub = fixed(aSuf.slice(1), '9'.repeat(remLen));
    parts.push(ad + sub);
  }
  // group 2: middle digits (ad+1 .. bd-1) + any
  const lo = +ad + 1, hi = +bd - 1;
  if (lo <= hi) {
    const any = remLen === 0 ? '' : (remLen === 1 ? '[0-9]' : '[0-9]' + (remLen>1 ? '{'+remLen+'}' : ''));
    // Wait if remLen==1 => [0-9]
    parts.push(charClass(lo, hi) + anyDigits(remLen));
  }
  // group 3: b's branch: bd + fixed('0'*remLen, bSuf.slice(1))
  if (remLen === 0) {
    parts.push(bd);
  } else {
    const sub = fixed('0'.repeat(remLen), bSuf.slice(1));
    parts.push(bd + sub);
  }
  const inner = parts.join('|');
  // combine with prefix; if prefix non-empty and multiple parts, wrap
  if (prefix === '') {
    return inner;
  }
  return prefix + (parts.length === 1 ? inner : '(' + inner + ')');
}
```

