const ANY_DIGIT = '[0-9]';

function anyDigits(count) {
  if (count === 0) return '';
  if (count === 1) return ANY_DIGIT;
  return `${ANY_DIGIT}{${count}}`;
}

function charClass(low, high) {
  if (low === high) return String(low);
  if (high - low === 1) return `[${low}${high}]`;
  return `[${low}-${high}]`;
}

function fixedWidthRegex(low, high) {
  if (low === high) return low;

  let i = 0;
  while (i < low.length && low[i] === high[i]) i += 1;

  const prefix = low.slice(0, i);
  const lowSuffix = low.slice(i);
  const highSuffix = high.slice(i);
  const remaining = lowSuffix.length - 1;
  const parts = [];

  const lowSub =
    remaining === 0
      ? String(lowSuffix[0])
      : lowSuffix[0] + fixedWidthRegex(lowSuffix.slice(1), '9'.repeat(remaining));
  parts.push(lowSub);

  const middleLow = Number(lowSuffix[0]) + 1;
  const middleHigh = Number(highSuffix[0]) - 1;
  if (middleLow <= middleHigh) {
    parts.push(charClass(middleLow, middleHigh) + anyDigits(remaining));
  }

  const highSub =
    remaining === 0
      ? String(highSuffix[0])
      : highSuffix[0] + fixedWidthRegex('0'.repeat(remaining), highSuffix.slice(1));
  parts.push(highSub);

  const body = parts.join('|');
  if (prefix === '') return body;
  return parts.length === 1 ? prefix + body : `${prefix}(?:${body})`;
}

function assertRange(min, max) {
  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError('range bounds must be integers');
  }
  if (min < 0 || max < 0) {
    throw new RangeError('range bounds must be non-negative');
  }
  if (min > max) {
    throw new RangeError(`invalid range: ${min} > ${max}`);
  }
}

export function toRegexSource(min, max) {
  assertRange(min, max);

  const maxDigits = String(max).length;
  const alternatives = [];

  for (let digits = String(min).length; digits <= maxDigits; digits += 1) {
    const lower = Math.max(min, digits === 1 ? 0 : 10 ** (digits - 1));
    const upper = Math.min(max, 10 ** digits - 1);
    if (lower > upper) continue;

    alternatives.push(fixedWidthRegex(String(lower), String(upper)));
  }

  if (alternatives.length === 1) {
    return `^(?:${alternatives[0]})$`;
  }
  return `^(?:${alternatives.join('|')})$`;
}

export function rangeToRegex(min, max, flags) {
  return new RegExp(toRegexSource(min, max), flags);
}

export function parseRange(range) {
  if (typeof range !== 'string') {
    throw new TypeError('range must be a string like "1-100"');
  }

  const match = /^\s*(\d+)\s*-\s*(\d+)\s*$/.exec(range);
  if (!match) {
    throw new SyntaxError(`invalid range: "${range}" (expected "min-max")`);
  }

  return { min: Number(match[1]), max: Number(match[2]) };
}

export function rangeToRegexFromString(range, flags) {
  const { min, max } = parseRange(range);
  return rangeToRegex(min, max, flags);
}

#!/usr/bin/env node
import { parseRange, toRegexSource } from '../src/range-to-regex.js';

const USAGE = `Usage: range-to-regex <min-max> [number]

Prints a regular expression matching any integer in the given range.
If a number is supplied, reports whether it matches.

Examples:
  range-to-regex 1-100
  range-to-regex 1-100 42`;

function main(argv) {
  if (argv.length === 0 || argv.includes('-h') || argv.includes('--help')) {
    console.log(USAGE);
    return argv.length === 0 ? 1 : 0;
  }

  const [range, number] = argv;
  let source;
  try {
    const { min, max } = parseRange(range);
    source = toRegexSource(min, max);
  } catch (error) {
    console.error(`error: ${error.message}`);
    return 1;
  }

  console.log(source);

  if (number !== undefined) {
    if (!/^\d+$/.test(number)) {
      console.error(`error: "${number}" is not a non-negative integer`);
      return 1;
    }
    const matches = new RegExp(source).test(number);
    console.log(matches ? `match: ${number}` : `no match: ${number}`);
    return matches ? 0 : 1;
  }

  return 0;
}

process.exitCode = main(process.argv.slice(2));

import assert from 'node:assert/strict';
import test from 'node:test';
import {
  parseRange,
  rangeToRegex,
  rangeToRegexFromString,
  toRegexSource,
} from '../src/range-to-regex.js';

test('parseRange parses and trims whitespace', () => {
  assert.deepEqual(parseRange('1-100'), { min: 1, max: 100 });
  assert.deepEqual(parseRange(' 0 - 9 '), { min: 0, max: 9 });
});

test('parseRange rejects malformed input', () => {
  assert.throws(() => parseRange('100'), SyntaxError);
  assert.throws(() => parseRange('1..100'), SyntaxError);
  assert.throws(() => parseRange(100), TypeError);
});

test('toRegexSource rejects invalid bounds', () => {
  assert.throws(() => toRegexSource(100, 1), RangeError);
  assert.throws(() => toRegexSource(-1, 10), RangeError);
  assert.throws(() => toRegexSource(1.5, 10), TypeError);
});

test('rangeToRegex returns a usable RegExp', () => {
  const re = rangeToRegexFromString('1-100');
  assert.ok(re instanceof RegExp);
  assert.ok(re.test('1'));
  assert.ok(re.test('42'));
  assert.ok(re.test('100'));
  assert.ok(!re.test('0'));
  assert.ok(!re.test('101'));
  assert.ok(!re.test('1.5'));
  assert.ok(!re.test('007'));
});

test('single-value range matches literal', () => {
  const re = rangeToRegex(7, 7);
  assert.ok(re.test('7'));
  assert.ok(!re.test('8'));
});

test('full membership matches for many small ranges', () => {
  const MAX = 120;
  for (let min = 0; min <= MAX; min += 1) {
    for (let max = min; max <= MAX; max += 1) {
      const re = rangeToRegex(min, max);
      for (let n = 0; n <= MAX + 5; n += 1) {
        const expected = n >= min && n <= max;
        assert.equal(
          re.test(String(n)),
          expected,
          `range ${min}-${max} testing ${n} (source ${re.source})`,
        );
      }
    }
  }
});

test('regex does not accept leading zeros', () => {
  const re = rangeToRegex(0, 100);
  for (const value of ['00', '01', '0100', '0000']) {
    assert.ok(!re.test(value), `should not match ${value}`);
  }
});

